appearance.custom_css:
/* Schartau Industrial 1.0 · responsive LorzCMS design */
.cms-page{--site-width:1320px;--page-radius:0;color:#20282c;background:#f3f1ea;font-family:Manrope,"Segoe UI",Arial,sans-serif}
.cms-page .site-container{width:min(calc(100% - 4rem),1320px)}
.cms-page .site-header{position:relative;z-index:8;border:0;background:#141c21;color:#fff;box-shadow:0 16px 40px #10171a25}
.cms-page .header-inner{min-height:96px;padding-block:1.1rem}
.cms-page .site-brand{max-width:360px;letter-spacing:-.04em;font-size:clamp(1.18rem,2vw,1.65rem);font-weight:850;text-transform:uppercase}
.cms-page .site-brand::before{content:"▰";display:inline-block;margin-right:.66rem;color:#ffc400;font-size:1.22em;transform:skew(-12deg)}
.cms-page .site-navigation>ul{gap:.2rem .35rem}
.cms-page .site-navigation a{font-size:.85rem;font-weight:750;letter-spacing:.015em;text-decoration:none!important;padding:.9rem 1.05rem;border-radius:4px;transition:background .2s,color .2s}
.cms-page .site-navigation a:hover,.cms-page .site-navigation a[aria-current]{background:#ffc400;color:#171a1d}
.cms-page .site-navigation>ul>li:last-child>a{background:#ffc400;color:#14191b;border-radius:2px}
.cms-page .site-navigation>ul>li:last-child>a::after{content:" ↗";font-weight:800}
.cms-page .landing-intro{width:100%;max-width:none;min-height:clamp(540px,66vh,760px);display:flex;align-items:center;text-align:left;padding:6rem max(2rem,calc((100vw - 1320px)/2));position:relative;isolation:isolate;overflow:hidden;background:#20282c}
.cms-page .landing-intro::before{content:"";position:absolute;inset:0;z-index:-2;background:linear-gradient(90deg,rgba(13,21,25,.98) 0%,rgba(17,27,31,.88) 39%,rgba(17,27,31,.26) 84%),url("https://images.unsplash.com/photo-1707062358488-41594b7d6290?auto=format&fit=crop&w=2000&q=85") center 48%/cover no-repeat}
.cms-page .landing-intro::after{content:"";position:absolute;z-index:-1;right:-5%;top:0;bottom:0;width:24%;background:repeating-linear-gradient(130deg,transparent 0,transparent 65px,#ffc40027 65px,#ffc40027 99px);pointer-events:none}
.cms-page .landing-intro .page-intro{margin:0;width:100%;max-width:920px;text-shadow:0 2px 20px #0005}
.cms-page .page-eyebrow{font-size:.84rem;font-weight:800;letter-spacing:.19em;color:#ffc400;text-transform:uppercase;margin-bottom:2rem}
.cms-page h1{color:#fff;font-size:clamp(3.5rem,7vw,7.1rem);max-width:13ch;font-weight:850;line-height:.99;letter-spacing:-.07em;text-transform:uppercase;text-wrap:balance}
.cms-page .landing-intro .page-intro::after{content:"REGIONAL. ZUVERLÄSSIG. UNKOMPLIZIERT.";display:block;width:max-content;max-width:100%;padding:1rem 1.4rem;margin-top:2.8rem;background:#ffc400;color:#171b1d;font-size:clamp(.65rem,1.15vw,.89rem);font-weight:850;letter-spacing:.105em;box-shadow:8px 8px 0 #ffffff1b;text-shadow:none}
.cms-page .landing-body>.page-content{background:linear-gradient(90deg,#e2e0d4 0 4px,transparent 4px) 0 0/100% 100% no-repeat;min-height:26rem;border:0;padding:clamp(3.5rem,6vw,7rem) min(3vw,3rem) 7rem}
.cms-page .page-content>.rich{max-width:100%;font-size:1.07rem;line-height:1.87;color:#3a4548;display:flow-root}
.cms-page .page-content>.rich>p:first-child{font-size:clamp(1.3rem,2.1vw,1.75rem);max-width:74ch;color:#1b282d;line-height:1.65;font-weight:540}
.cms-page .page-content h2{font-weight:850;max-width:24ch;text-transform:uppercase;letter-spacing:-.045em;color:#1c272c;font-size:clamp(2rem,3.3vw,3.5rem);margin-top:3.5rem;margin-bottom:1.3rem}
.cms-page .page-content h2::before{content:"";display:block;width:72px;height:7px;margin-bottom:1.3rem;background:#ffc400;transform:skew(-20deg)}
.cms-page .page-content h3{font-weight:800;font-size:1.32rem}
.cms-page .page-content ul{padding:0;list-style:none;display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1rem;margin:2.4rem 0}
.cms-page .page-content li{position:relative;background:#fff;padding:1.4rem 1.45rem 1.45rem 2.65rem;box-shadow:0 12px 32px #1f29200b;border-bottom:4px solid #ffc400;font-weight:660;color:#273136}
.cms-page .page-content li::before{content:"↗";position:absolute;left:1rem;color:#ad8700;font-weight:900}
.cms-page .page-content a{font-weight:800;color:#956900;text-decoration-thickness:2px}
.cms-page .page-content a:hover{color:#1d2327}
.cms-page .page-content blockquote{background:#202b2e;color:#fff;border-left:8px solid #ffc400;padding:2rem 2.4rem}
.cms-page .site-footer{background:#131a1e;color:#e9e9e2;padding-block:4.4rem 2rem;border-top:8px solid #ffc400}
.cms-page .footer-inner{gap:5rem}
.cms-page .site-footer .site-brand{font-size:1.65rem;color:#fff}
.cms-page .site-footer p,.cms-page .site-footer a{color:#c3c8c4}
.cms-page .site-footer a:hover{color:#ffc400}
.cms-page .site-navigation ul ul{background:#202a2f;color:#fff;border:1px solid #3a4447}
.cms-page .site-navigation ul ul a:hover{color:#171b1d}
.cms-page .cms-block{border-radius:0;border:0;border-left:6px solid #ffc400;background:#fff;box-shadow:0 8px 30px #13212012}
@media(min-width:901px){.cms-page .page-content>.rich>p{max-width:78ch}}
@media(max-width:900px){.cms-page .site-container{width:calc(100% - 2rem)}.cms-page .header-inner{gap:1.2rem}.cms-page .landing-intro{padding-inline:2rem;min-height:540px}.cms-page h1{font-size:clamp(3.15rem,11vw,5.7rem)}}
@media(max-width:760px){.cms-page .site-header{position:relative}.cms-page .header-inner{padding-block:1.25rem}.cms-page .site-brand{font-size:1.35rem}.cms-page .site-navigation{width:100%;overflow:visible}.cms-page .site-navigation>ul{display:flex;gap:.25rem}.cms-page .site-navigation>ul>li:last-child>a{padding:.55rem .75rem}.cms-page .site-navigation a{font-size:.77rem;padding:.56rem .6rem}.cms-page .landing-intro{padding:4.5rem 1.25rem;min-height:540px}.cms-page .landing-intro::before{background:linear-gradient(90deg,#10191feE,#131d22ad),url("https://images.unsplash.com/photo-1707062358488-41594b7d6290?auto=format&fit=crop&w=1000&q=80") 55% center/cover}.cms-page .landing-intro .page-intro::after{line-height:1.45}.cms-page .landing-body>.page-content{padding:3rem 1rem 5rem}.cms-page .page-content li{padding:1.1rem 1.2rem 1.1rem 2.6rem}.cms-page .site-footer{padding-block:3rem}}
@media(prefers-reduced-motion:reduce){.cms-page *{transition:none!important}}
